import React from 'react';
import {
  Page,
  PageSection,
  Title,
  Card,
  CardTitle,
  CardBody,
  Button,
  Text,
  Grid,
  GridItem,
  Label
} from '@patternfly/react-core';
import { BuilderImageIcon, CubesIcon, PlayIcon } from '@patternfly/react-icons';

const App: React.FC = () => {
  const [environments, setEnvironments] = React.useState([]);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    // Fetch environments from our API
    fetch('http://localhost:8000/api/environments')
      .then(res => res.json())
      .then(data => {
        setEnvironments(data);
        setLoading(false);
      })
      .catch(err => {
        console.error('Failed to fetch environments:', err);
        setLoading(false);
      });
  }, []);

  return (
    <Page>
      {/* Header Section */}
      <PageSection variant="light">
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '16px' }}>
          <BuilderImageIcon style={{ marginRight: '12px', color: '#0066cc', fontSize: '2rem' }} />
          <Title headingLevel="h1" size="2xl">
            EE Containers Builder
          </Title>
        </div>
        <Text component="p">
          Build and manage Ansible Execution Environments with ease
        </Text>
      </PageSection>

      {/* Main Content */}
      <PageSection>
        <Title headingLevel="h2" size="xl" style={{ marginBottom: '24px' }}>
          <CubesIcon style={{ marginRight: '12px' }} />
          Dashboard
        </Title>

        <Grid hasGutter>
          <GridItem lg={6} md={12}>
            <Card>
              <CardTitle>Available Environments</CardTitle>
              <CardBody>
                {loading ? (
                  <Text>Loading environments...</Text>
                ) : (
                  <div>
                    {environments.map((env: any) => (
                      <div key={env.name} style={{ marginBottom: '16px', padding: '12px', border: '1px solid #d2d2d2', borderRadius: '4px' }}>
                        <Title headingLevel="h4" size="md" style={{ marginBottom: '8px' }}>
                          {env.name}
                        </Title>
                        <Text component="small" style={{ display: 'block', marginBottom: '8px' }}>
                          {env.description}
                        </Text>
                        <div>
                          <Label color="blue">{env.type.toUpperCase()}</Label>
                          <Label color="purple" style={{ marginLeft: '8px' }}>
                            {env.os_version.toUpperCase()}
                          </Label>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardBody>
            </Card>
          </GridItem>

          <GridItem lg={6} md={12}>
            <Card>
              <CardTitle>Quick Actions</CardTitle>
              <CardBody>
                <Button
                  variant="primary"
                  icon={<PlayIcon />}
                  style={{ marginBottom: '16px' }}
                  onClick={() => alert('Build functionality coming soon!')}
                >
                  Start New Build
                </Button>
                <br />
                <div style={{ marginTop: '16px', padding: '12px', backgroundColor: '#f0f8ff', borderRadius: '4px' }}>
                  <Text component="small">
                    <strong>API Status:</strong> Connected ✅<br />
                    <strong>Backend URL:</strong> http://localhost:8000<br />
                    <strong>Environments Found:</strong> {environments.length}
                  </Text>
                </div>
              </CardBody>
            </Card>
          </GridItem>
        </Grid>
      </PageSection>
    </Page>
  );
};

export default App;
